package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_tan_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testTan_NaN() {
        Complex c = Complex.NaN;
        Complex result = c.tan();
        Assert.assertTrue("Result should be NaN", result.isNaN());
    }

    @Test
    public void testTan_Zero() {
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.tan();
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_RealOnly() {
        // tan(pi/4) = 1
        Complex c = new Complex(Math.PI / 4.0, 0.0);
        Complex result = c.tan();
        Assert.assertEquals(1.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_ImaginaryOnly() {
        // tan(i * y) = i * tanh(y)
        // Let y = 1.0
        double y = 1.0;
        Complex c = new Complex(0.0, y);
        Complex result = c.tan();

        double expectedReal = 0.0;
        double expectedImaginary = Math.tanh(y);

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImaginary, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_Complex() {
        // Test with a general complex number
        double re = 0.5;
        double im = 0.5;
        Complex c = new Complex(re, im);
        Complex result = c.tan();

        // Using the identity: tan(x + iy) = (sin(2x) + i*sinh(2y)) / (cos(2x) + cosh(2y))
        double real2 = 2.0 * re;
        double imag2 = 2.0 * im;
        double d = Math.cos(real2) + Math.cosh(imag2);
        double expectedReal = Math.sin(real2) / d;
        double expectedImag = Math.sinh(imag2) / d;

        Assert.assertEquals(expectedReal, result.getReal(), EPSILON);
        Assert.assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }

    @Test
    public void testTan_LargeImaginary() {
        // As imaginary part goes to infinity, tan(z) approaches i
        Complex c = new Complex(0.0, 100.0);
        Complex result = c.tan();
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(1.0, result.getImaginary(), EPSILON);
    }
}
